#!/usr/bin/env python3
"""Tests of code generated by `frontx_compile` (`Proven/Frontx/Machine.lean`, `ForMachine.lean`; words from
`asm/emit_frontx.lean` in `asm/arr-words/`) on QEMU and on the Sail C emulator.

check N [crc|b64sum|find|be32]: N random inputs.  Each case has its own input slot (followed by 16 guard bytes) and
its own 256-byte stack with `sp` at a random misalignment; the driver calls the code with a0 = input, a1 = length
and the function's other arguments in a2..a4, and stores a2, gp, sp and the instruction count.  Checked on both:
a2 = the reference computed in Python, input and guards unchanged, gp and sp restored, every stack byte outside the
frame unchanged, and (Sail) every data write inside a frame or the result table.
usage: frontx_test.py check N [function]"""
import os, random, re, subprocess, sys, time, zlib
D = os.path.dirname(os.path.abspath(__file__)); W = os.path.join(D, "ctest"); os.makedirs(W, exist_ok=True)
SAIL = "/home/user/deps/sailsim/sail-riscv-Linux-x86_64/bin/sail_riscv_sim"
p = lambda f: os.path.join(W, f)
sh = lambda c: subprocess.run(c, shell=True, check=True)
G, ST, E = 16, 256, 88
MAGIC = 0x0123456789ABCDEF
LD = "ENTRY(_start)\nSECTIONS { . = 0x80000000; .text : { *(.text.start) *(.text) }\n . = 0x80100000; .tohost : { *(.tohost) }\n . = 0x80200000; .data : { *(.data) } }\n"
# table entry: in, len, sp, gp-in, a2, a3, a4 | a2-out, gp-out, sp-out, instret
DRIVER = """.section .text.start
.globl _start
_start: lla s0, tab
  li s2, %d
1: ld a0, 0(s0)
  ld a1, 8(s0)
  ld a2, 32(s0)
  ld a3, 40(s0)
  ld a4, 48(s0)
  ld sp, 16(s0)
  ld gp, 24(s0)
  csrr s3, minstret
  jal ra, func
  csrr s4, minstret
  sub s4, s4, s3
  sd a2, 56(s0)
  sd gp, 64(s0)
  sd sp, 72(s0)
  sd s4, 80(s0)
  addi s0, s0, %d
  addi s2, s2, -1
  bnez s2, 1b
  lla t0, tohost
  li t1, 1
  sd t1, 0(t0)
halt: j halt
func:
%s.section .tohost,"aw"
.globl tohost
.globl fromhost
.align 6
tohost: .dword 0
fromhost: .dword 0
"""

def qemu(name, halt, a, n):
    q = subprocess.Popen(f"qemu-system-riscv64 -machine virt -m 1G -bios {p(name + '.elf')} -display none -serial none "
                         f"-monitor stdio -icount shift=0", shell=True, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                         text=True, bufsize=0)
    def hmp(c):
        q.stdin.write(c + "\n"); buf = ""
        while not buf.endswith("(qemu) ") or c not in buf: buf += q.stdout.read(1)
        return buf
    hmp("info version"); t0 = time.time()
    while "pc       %016x" % halt not in hmp("info registers"):
        assert time.time() - t0 < 600, "QEMU did not reach halt"; time.sleep(0.01)
    hmp(f'pmemsave {a:#x} {n} "{p(name + ".q.bin")}"'); q.stdin.write("quit\n"); q.wait()
    return open(p(name + ".q.bin"), "rb").read()

def b64digit(c):
    if 65 <= c <= 90: return c - 65
    if 97 <= c <= 122: return c - 71
    if 48 <= c <= 57: return c + 4
    return 62 if c == 43 else 63 if c == 47 else 64
at = lambda xs, i: xs[i] if i < len(xs) else 0
# name -> (slots, args(rng, xs) -> (a2, a3, a4), reference(xs, a2, a3, a4) -> expected a2)
FUNCS = {
    "crc": (12, lambda rng, xs: (0, 0xFFFFFFFF, 0), lambda xs, i, c, _: zlib.crc32(xs) ^ 0xFFFFFFFF),
    "b64sum": (10, lambda rng, xs: (rng.randrange(len(xs) + 2), rng.randrange(len(xs) + 5), rng.randrange(2 ** 32)),
               lambda xs, i, fuel, n: (n + sum(b64digit(at(xs, k)) for k in range(i, i + fuel))) % 2 ** 32),
    "find": (8, lambda rng, xs: (rng.randrange(len(xs) + 3), rng.choice(list(xs) + [rng.randrange(256)]), 0),
             lambda xs, i, c, _: next((k for k in range(i, len(xs)) if xs[k] == c), len(xs))),
    "be32": (6, lambda rng, xs: (rng.randrange(len(xs) + 3), 0, 0),
             lambda xs, i, *_: at(xs, i) << 24 | at(xs, i + 1) << 16 | at(xs, i + 2) << 8 | at(xs, i + 3)),
}

def check(N, fn):
    slots, mkargs, ref = FUNCS[fn]
    FR = 8 * (slots + 1)
    rng = random.Random(5)
    lens = ([0, 1, 2, 3, 9, 255, 256, 257] + [rng.choice([rng.randrange(40), rng.randrange(600)]) for _ in range(N)])[:N]
    cases = [bytes([0x31 + i for i in range(9)]) if L == 9 else bytes(rng.randrange(256) for _ in range(L)) for L in lens]
    func = "".join(f"  .word 0x{int(l, 16):08x}\n" for l in open(os.path.join(D, "arr-words", fn + ".words")) if l.strip())
    args = [mkargs(rng, xs) for xs in cases]
    data, tab, off, lay = [], [], 0, []
    for xs, ar in zip(cases, args):
        L = len(xs); i0 = off; k0 = i0 + L + G; off = k0 + ST
        sp = k0 + ST - 8 - rng.randrange(8)
        lay.append((i0, k0, sp))
        tab.append(f"  .quad base+{i0}, {L}, base+{sp}, {MAGIC}, {ar[0]}, {ar[1]}, {ar[2]}, 0, 0, 0, 0")
        data.append(xs + b"\xAA" * G + b"\x77" * ST)
    open(p("crc.bin"), "wb").write(b"".join(data))
    open(p("crc.S"), "w").write(DRIVER % (len(cases), E, func) +
        f'.data\n.align 4\nbase:\n.incbin "{p("crc.bin")}"\n.align 3\ntab:\n' + "\n".join(tab) + "\n")
    open(p("m.ld"), "w").write(LD)
    sh(f"riscv64-linux-gnu-gcc -march=rv64i_zicsr -mabi=lp64 -nostdlib -static -Wl,-T,{p('m.ld')} -Wl,--no-relax "
       f"-Wl,--build-id=none {p('crc.S')} -o {p('crc.elf')}")
    syms = subprocess.check_output(f"riscv64-linux-gnu-nm {p('crc.elf')}", shell=True, text=True)
    sym = lambda s: int(re.search(rf"(\w+) \w {s}\n", syms).group(1), 16)
    halt, base, tabA = sym("halt"), sym("base"), sym("tab")
    qmem = qemu("crc", halt, base, tabA + E * len(cases) - base)
    r = subprocess.run(f"{SAIL} --inst-limit 2000000000 --trace-mem --trace-output {p('sail.log')} {p('crc.elf')}",
                       shell=True, capture_output=True, text=True)
    assert "SUCCESS" in r.stdout + r.stderr, (r.stdout + r.stderr)[-500:]
    smem = bytearray(open(p("crc.bin"), "rb").read()) + bytearray(qmem[off:])
    pad = tabA - base - off
    allowed = set(range(tabA, tabA + E * len(cases)))
    for (i0, k0, sp) in lay:
        fp = sp // 8 * 8 - FR
        allowed |= set(range(base + fp, base + fp + FR))
    tabm = bytearray(E * len(cases))
    for l in open(p("sail.log")):
        m = re.match(r"mem\[(?:W,)?0x([0-9A-F]+)\] <- 0x([0-9A-F]+)", l)
        if not m: continue
        a, v = int(m.group(1), 16), m.group(2)
        if a < base: continue
        nb = len(v) // 2
        for j in range(nb):
            assert a + j in allowed, f"unexpected Sail write {l.strip()}"
            b = int(v[2 * (nb - 1 - j):2 * (nb - j)], 16)
            if a + j >= tabA: tabm[a + j - tabA] = b
            else: smem[a + j - base] = b
    stab = bytes(tabm); qtab = qmem[tabA - base:]
    tot = 0
    for nm, mem, tb in (("qemu", qmem, qtab), ("sail", smem, stab)):
        for c, ((i0, k0, sp), xs, ar) in enumerate(zip(lay, cases, args)):
            L = len(xs); fp = sp // 8 * 8 - FR
            assert bytes(mem[i0:i0 + L + G]) == xs + b"\xAA" * G, (nm, "input", L)
            st = mem[k0:k0 + ST]
            assert all(b == 0x77 for j, b in enumerate(st) if not (fp - k0 <= j < fp - k0 + FR)), (nm, "stack", L)
            a2, gp, spo, cnt = (int.from_bytes(tb[E * c + o:E * c + o + 8], "little") for o in (56, 64, 72, 80))
            assert a2 == ref(xs, *ar), (nm, fn, L, ar, hex(a2))
            assert gp == MAGIC and spo == base + sp, (nm, "gp/sp")
            if nm == "qemu": tot += cnt
    nb = sum(map(len, cases))
    print(f"{fn}: {len(cases)} cases ok (QEMU == Sail == reference; lengths up to {max(map(len, cases))}); "
          f"{tot} instructions, {nb} input bytes ({tot / len(cases):.0f} per call)")

for fn in (sys.argv[3:] or list(FUNCS)): check(int(sys.argv[2]), fn)
